// ═══ BUG: synchronized on String literal ═══
// Class A (AccountService):
synchronized ("ACCOUNT_LOCK") {
    account.debit(amount);
}

// Class B (ReportService — completely unrelated!):
synchronized ("ACCOUNT_LOCK") {
    generateReport();  // takes 30 seconds!
}

// "ACCOUNT_LOCK" is a String literal → INTERNED → same object in memory!
// Class A and Class B lock on the SAME string instance!
// While report generates (30 sec), ALL account debits are BLOCKED!
// These classes don't even know about each other!

// ═══ PROOF: String literals are the same object ═══
String a = "LOCK";
String b = "LOCK";
System.out.println(a == b);  // TRUE! Same interned instance!

// ═══ SAME BUG: Boolean, Integer cache ═══
synchronized (Boolean.TRUE) { }     // EVERY class using Boolean.TRUE shares this lock!
synchronized (Integer.valueOf(1)) { } // cached [-128..127] → shared!

// ═══ FIX: private final Object ═══
public class AccountService {
    private final Object lock = new Object();  // UNIQUE to this class!

    public void debit(BigDecimal amount) {
        synchronized (lock) {
            balance = balance.subtract(amount);
        }
    }
}
// 'lock' is:
// PRIVATE → no external code can access it → no accidental shared locking
// FINAL → can't be reassigned → always the same lock object
// new Object() → unique instance → not shared with anyone

// ═══ ANTI-PATTERNS ═══
// (Avoid) synchronized("LOCK")         → interned string, shared globally!
// (Avoid) synchronized(this)           → external code can lock on your object!
// (Avoid) synchronized(Boolean.TRUE)   → globally cached, shared!
// (Avoid) synchronized(Integer.valueOf(0)) → cached, shared!
// (Avoid) Object lock = new Object();  → NOT final, can be reassigned!
//    lock = new Object();         → now different lock! Synchronization BROKEN!

// (Recommended) private final Object lock = new Object();  → ALWAYS correct!
