// ─── File: src/test/java/com/bank/lockbug/StringLockBugTest.java ───
package com.bank.lockbug;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;

class StringLockBugTest {

    // ═══ PROOF: String literals are the same object ═══
    @Test
    void stringLiterals_sameInstance() {
        String a = "ACCOUNT_LOCK";
        String b = "ACCOUNT_LOCK";
        assertThat(a == b).isTrue();  // SAME object! Interned!
    }

    // ═══ BUG: two unrelated classes block each other ═══
    @Test
    void stringLock_unrelatedClassesBlock() throws InterruptedException {
        CountDownLatch lockHeld = new CountDownLatch(1);

        // "Service A" holds the string lock for 500ms
        Thread serviceA = new Thread(() -> {
            synchronized ("SHARED_LOCK") {
                lockHeld.countDown();
                try { Thread.sleep(500); } catch (InterruptedException e) { }
            }
        });
        serviceA.start();
        lockHeld.await();

        // "Service B" tries the SAME string lock — BLOCKED!
        long start = System.currentTimeMillis();
        synchronized ("SHARED_LOCK") {
            // This is reached only AFTER serviceA releases!
        }
        long elapsed = System.currentTimeMillis() - start;

        assertThat(elapsed).isGreaterThanOrEqualTo(300);  // was blocked ~500ms!
        serviceA.join();
    }

    // ═══ FIX: private final Object — no accidental sharing ═══
    static class AccountService {
        private final Object lock = new Object();

        void debit() throws InterruptedException {
            synchronized (lock) {
                Thread.sleep(100);
            }
        }
    }

    static class AuditService {
        private final Object lock = new Object();  // DIFFERENT lock object!

        void generateReport() throws InterruptedException {
            synchronized (lock) {
                Thread.sleep(500);
            }
        }
    }

    @Test
    void privateLock_noAccidentalSharing() throws InterruptedException {
        AccountService accounts = new AccountService();
        AuditService audit = new AuditService();
        CountDownLatch auditStarted = new CountDownLatch(1);

        Thread auditThread = new Thread(() -> {
            auditStarted.countDown();
            try { audit.generateReport(); } catch (InterruptedException e) { }
        });
        auditThread.start();
        auditStarted.await();

        // Account debit NOT blocked by audit — different lock objects!
        long start = System.currentTimeMillis();
        accounts.debit();
        long elapsed = System.currentTimeMillis() - start;

        assertThat(elapsed).isLessThan(300);  // NOT blocked by audit!
        auditThread.join();
    }

    // ═══ ANTI-PATTERN: non-final lock can be reassigned ═══
    @Test
    void nonFinalLock_canBreak() {
        Object[] lock = {new Object()};  // simulate non-final

        Object lockBefore = lock[0];
        lock[0] = new Object();  // reassigned!
        Object lockAfter = lock[0];

        assertThat(lockBefore).isNotSameAs(lockAfter);
        // If synchronized(lock[0]): before and after use DIFFERENT locks!
        // Synchronization BROKEN!
    }
}
